Write a pytest asyncio test for an async retry helper that succeeds on the third attempt and verify the attempt count.

import asyncio

async def async_retry(fn, attempts=3):
    last = None
    for _ in range(attempts):
        try:
            return await fn()
        except Exception as exc:
            last = exc
    raise last

Write a pytest asyncio test for an async iterator class that implements __aiter__/__anext__ over a list of values.

class AsyncRange:
    def __init__(self, n):
        self.n = n
        self.i = 0
    def __aiter__(self):
        return self
    async def __anext__(self):
        if self.i >= self.n:
            raise StopAsyncIteration
        self.i += 1
        return self.i - 1

