import pytest
from httpc import HttpClient

@pytest.mark.asyncio
async def test_get_json_mocked():
    client = HttpClient()
    client.get_json = AsyncMock(side_effect=[{'id': 1}, {'id': 2}])
    assert await client.get_json('/a') == {'id': 1}
    assert await client.get_json('/b') == {'id': 2}
